"""Explicit comparison of saved synthetic purchases, with frozen history."""
CSS='''
#purchase-comparison{font-family:Arial,sans-serif;overflow-wrap:anywhere}
#purchase-comparison .comparison-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 18px}
#purchase-comparison .comparison-fields label{min-width:0}
#purchase-comparison .comparison-check{display:flex;align-items:center;gap:10px;margin:16px 0}
#purchase-comparison input[type=checkbox]{display:inline-block;width:18px;min-width:18px;margin:0}
#purchase-comparison .comparison-quota{display:grid;grid-template-columns:1fr 1fr 1fr auto;gap:10px;align-items:end;margin:12px 0}
#purchase-comparison .comparison-quota label{margin:0}
#purchase-comparison .comparison-scroll{overflow-x:auto;max-width:100%;margin:14px 0;border:1px solid #b9cce6;border-radius:8px}
#purchase-comparison table{min-width:780px}
#purchase-comparison th{background:#e1effb;color:#183c68}
#purchase-comparison th,#purchase-comparison td{vertical-align:top}
#purchase-comparison .comparison-result{border:1px solid #b9cce6;background:#f3f8ff;border-radius:9px;padding:16px;margin-top:18px}
#purchase-comparison .comparison-result h3{margin-top:0;font-weight:700}
#purchase-comparison .comparison-status{white-space:pre-wrap;margin:12px 0;color:#173e76}
#purchase-comparison .comparison-quota button{margin:0}
@media(max-width:900px){#purchase-comparison .comparison-fields{grid-template-columns:1fr}#purchase-comparison .comparison-quota{grid-template-columns:1fr 1fr}}
'''
JS=r'''
let purchaseComparisonSequence=0;
function renderPurchaseComparisonSaved(proposal){
 let submitted=false;const sequence=++purchaseComparisonSequence,dataset=$('dataset').value;
 let box=$('purchase-comparison');if(!box){box=document.createElement('section');box.id='purchase-comparison';box.className='card';$('review-panel').append(box)}box.replaceChildren();
 const h=document.createElement('h2');h.textContent='COMPARAR CONDICIONES DE COMPRA';box.append(h);
 const note=document.createElement('p');note.textContent='Compara la misma cantidad y proveedor, con o sin déficit. Las referencias y aceptaciones declaradas quedan sin verificar. Guardar no modifica la propuesta original. La previsión compensa movimientos al cierre de cada día y no garantiza cobros, disponibilidad actual ni cobertura completa de obligaciones.';box.append(note);
 const panel=document.createElement('div');panel.className='comparison-fields';box.append(panel);const fields={};function input(key,label,type='text'){const l=document.createElement('label'),i=document.createElement('input');l.textContent=label;i.type=type;l.append(i);panel.append(l);fields[key]=i;return i}
 input('label','Nombre de la alternativa').value='Alternativa de negociación';input('actor','Responsable');
 input('price','Nuevo precio por unidad (opcional)','number').step='any';input('discount','Descuento porcentual alternativo (opcional)','number').step='any';input('due','Nuevo vencimiento de mercancía (opcional)','date');
 const originLabel=document.createElement('label');originLabel.textContent='Origen de las condiciones modificadas';const origin=document.createElement('select');for(const [v,t] of [['HYPOTHETICAL','Hipótesis para negociar'],['DOCUMENTED','Oferta documentada, sin verificar'],['UNCONFIRMED','Sin confirmar']]){const o=document.createElement('option');o.value=v;o.textContent=t;origin.append(o)}originLabel.append(origin);panel.append(originLabel);
 input('source','Referencia del soporte (obligatoria para oferta documentada)');
 const quotaLabel=document.createElement('label'),quotaEnabled=document.createElement('input');quotaEnabled.type='checkbox';quotaLabel.className='comparison-check';quotaLabel.append(quotaEnabled,document.createTextNode(' Sustituir el calendario completo de cuotas'));box.append(quotaLabel);const quotas=document.createElement('div');quotas.hidden=true;box.append(quotas);const addQuota=document.createElement('button');addQuota.type='button';addQuota.textContent='Añadir cuota';quotas.append(addQuota);const quotaRows=[];addQuota.onclick=()=>{const row=document.createElement('div'),component=document.createElement('select'),amount=document.createElement('input'),due=document.createElement('input'),remove=document.createElement('button');for(const [v,t] of [['MERCHANDISE','Mercancía'],['FREIGHT','Portes']]){const o=document.createElement('option');o.value=v;o.textContent=t;component.append(o)}amount.type='number';amount.step='0.01';amount.min='0.01';amount.setAttribute('aria-label','Importe de cuota con IVA');due.type='date';due.setAttribute('aria-label','Vencimiento de cuota');remove.type='button';remove.textContent='Eliminar cuota';row.className='comparison-quota';for(const [text,control] of [['Concepto',component],['Importe con IVA',amount],['Vencimiento',due]]){const label=document.createElement('label');label.textContent=text;label.append(control);row.append(label)}row.append(remove);quotas.append(row);const item={row,component,amount,due};quotaRows.push(item);remove.onclick=()=>{quotaRows.splice(quotaRows.indexOf(item),1);row.remove()}};quotaEnabled.onchange=()=>{quotas.hidden=!quotaEnabled.checked};
 const button=document.createElement('button');button.type='button';button.textContent='Comparar y conservar estudio';box.append(button);
 const status=document.createElement('p');status.className='comparison-status';status.setAttribute('role','status');box.append(status);const output=document.createElement('div');output.setAttribute('aria-live','polite');box.append(output);
 function render(items){output.replaceChildren();for(const item of items){const r=item.record,title=document.createElement('h3');title.textContent=(item.stale?'HISTÓRICO DESACTUALIZADO · ':'ESTUDIO GUARDADO · ')+new Intl.DateTimeFormat('es-ES',{dateStyle:'short',timeStyle:'short',timeZone:'Europe/Madrid'}).format(new Date(r.created_at));const card=document.createElement('section');card.className='comparison-result';card.append(title);output.append(card);const table=document.createElement('table');const head=document.createElement('tr');for(const t of ['Condición','Total a pagar','Ahorro','Saldo mínimo','Falta para reserva','Fecha de saldo mínimo','Estado']){const th=document.createElement('th');th.textContent=t;head.append(th)}table.append(head);const rows=[{label:'Propuesta original',result:r.baseline,saving:'0'},...r.alternatives];for(const a of rows){const tr=document.createElement('tr'),v=a.result;for(const value of [a.label,v.total?money(v.total)+' EUR':'Pendiente',a.saving===null?'Pendiente':money(a.saving)+' EUR',v.scenario?money(v.scenario.minimum_balance)+' EUR':'Pendiente',v.scenario?money(v.scenario.deficit)+' EUR':'Pendiente',v.scenario?stockDate(v.scenario.minimum_date):'Pendiente',v.status==='PENDING'?v.message:v.status==='SHORTFALL'?'No respeta la reserva':'Respeta la reserva en el escenario']){const td=document.createElement('td');td.textContent=value;tr.append(td)}table.append(tr);if(a.conditions){const p=document.createElement('p');p.textContent=Object.entries(a.conditions).map(([k,c])=>({unit_price:'Precio por unidad',pricing_mode:'Modalidad de precio',discount_mode:'Modalidad de descuento',discount_value:'Descuento',due_date:'Vencimiento de mercancía',shipping_due_date:'Vencimiento de portes',payment_installments:'Calendario de cuotas'}[k]||'Condición')+': '+({DOCUMENTED:'Documentada, sin verificar',HYPOTHETICAL:'Hipótesis para negociar',UNCONFIRMED:'Sin confirmar'}[c.origin])+(c.source_reference?' · '+c.source_reference:'')+(c.validity_status==='EXPIRED_AT_COMPARISON'?' · VIGENCIA CADUCADA':'')).join('; ');card.append(p)}}const scroll=document.createElement('div');scroll.className='comparison-scroll';scroll.tabIndex=0;scroll.setAttribute('role','region');scroll.setAttribute('aria-label','Comparación de condiciones. Desplaza horizontalmente para ver todas las columnas.');scroll.append(table);card.append(scroll);const hint=document.createElement('small');hint.textContent='Desplaza la tabla horizontalmente para consultar todas las columnas.';card.append(hint);for(const a of rows){if(a.result.timeline&&typeof renderPurchaseTimeline==='function'){const subtitle=document.createElement('h3');subtitle.textContent='ESCENARIO · '+a.label;card.append(subtitle);renderPurchaseTimeline(card,a.result)}if(a.result.payments){const p=document.createElement('p');p.textContent=a.label+' · Pagos: '+a.result.payments.map(i=>stockDate(i.due_date)+': '+money(i.amount)+' EUR').join('; ');card.append(p)}}const p=document.createElement('p');p.textContent='Sin ganadora automática. No acredita viabilidad final ni aceptación verificada. Identificador: '+r.comparison_id;card.append(p)}}
 button.onclick=async()=>{submitted=true;button.disabled=true;status.textContent='Calculando y guardando la comparación…';try{const patch={};if(fields.price.value!=='')patch.unit_price=fields.price.value;if(fields.discount.value!==''){if(fields.price.value==='')throw Error('Indica el precio antes de descuentos para comparar el descuento.');patch.pricing_mode='BEFORE_DISCOUNT';patch.discount_mode='PERCENT';patch.discount_value=fields.discount.value}if(fields.due.value)patch.due_date=fields.due.value;if(quotaEnabled.checked)patch.payment_installments=quotaRows.map(i=>({component:i.component.value,amount:i.amount.value,due_date:i.due.value}));if(!Object.keys(patch).length)throw Error('Introduce un precio o vencimiento alternativo. Si hay cuotas, el nuevo vencimiento debe ser coherente con su calendario completo.');const conditions=Object.fromEntries(Object.keys(patch).map(k=>[k,{origin:origin.value,acceptance:'PENDING',source_reference:fields.source.value||null}]));const r=await api('/api/purchases/comparisons',{method:'POST',headers:{'Content-Type':'application/json','X-EIOS-Token':token},body:JSON.stringify({dataset_id:dataset,proposal_id:proposal.proposal_id,documentary_context_fingerprint:state.documentary_context.fingerprint,actor:fields.actor.value,alternatives:[{label:fields.label.value,patch,conditions}]})});if(sequence!==purchaseComparisonSequence||dataset!==$('dataset').value)return;render([{record:r,stale:false}]);status.textContent='ESTUDIO GUARDADO. La propuesta original permanece intacta.'}catch(e){if(sequence===purchaseComparisonSequence)status.textContent=e.message}finally{button.disabled=false}};
 api('/api/purchases/comparisons/read',{method:'POST',headers:{'Content-Type':'application/json','X-EIOS-Token':token},body:JSON.stringify({dataset_id:dataset,proposal_id:proposal.proposal_id})}).then(r=>{if(!submitted&&sequence===purchaseComparisonSequence&&dataset===$('dataset').value)render(r.comparisons)}).catch(e=>{if(sequence===purchaseComparisonSequence)status.textContent=e.message});
}
'''
